from pathlib import Path
p=Path(__file__).resolve().parent/'template.html'
s=p.read_text(encoding='utf-8')
s=s.replace('</style>','.pic{width:160px;height:130px;background:white}.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin:20px 0}.card{background:white;border:1px solid #dce4dd;border-radius:10px;padding:14px}.card img{width:100%;height:190px;object-fit:contain}.photo-link{display:block}.missing{padding:16px;background:#f5eee0;color:#88652c}.gallery-head{display:flex;align-items:center;gap:16px;flex-wrap:wrap}</style>')
s=s.replace('<div class="table">','<div class="gallery-head"><h2>厂家产品原图</h2><button id="allphotos">浏览全部候选图片</button></div><p class="small" id="photo-summary"></p><div class="gallery" id="gallery"></div><div class="table">')
s=s.replace("const dims=a=>a?a.join('×'):'未知';","const dims=a=>a?a.join('×'):'未知';\nlet allPhotos=false;function photoHTML(p,card=false){return p.photo?`<a class=\"photo-link\" href=\"${esc(p.photo)}\" target=\"_blank\" rel=\"noopener\" title=\"查看下载的厂家原图\"><img class=\"pic\" src=\"${esc(p.photo)}\" alt=\"${esc(p.model)}厂家型号页产品图\"></a><small>${esc(p.photo_caption)}</small><br><a href=\"${esc(p.photo_source)}\" target=\"_blank\" rel=\"noopener\">图片来源页</a>`:`<div class=\"missing\">${esc(p.photo_status)}${p.id==='WS17'?'；历史Rev1不使用Rev2照片代替。':''}</div>`;}\n")
start=s.index('const photo=p.photo?');end=s.index(';shown.push(',start)
s=s[:start]+"const photo=photoHTML(p)+(p.drawing?`<br><a href=\"${esc(p.drawing)}\" target=\"_blank\">机械尺寸图（非产品照片）</a>`:'')"+s[end:]
s=s.replace("window.screenReview={passed,visible:shown.length};","window.screenReview={passed,visible:shown.length};const pictured=pool.filter(p=>allPhotos||passed.includes(p.id));$('gallery').innerHTML=pictured.map(p=>`<article class=\"card\"><b>${esc(p.id)} ${esc(p.model)}</b>${photoHTML(p,true)}<p>${dims(p.module_mm)} mm · ${esc(p.bus)} · ${dims(p.resolution)} px</p></article>`).join('');$('photo-summary').textContent=`全池28条中，21条已补厂家产品图，1条为型号页版本待核图片，6条尚缺精确型号图。厂家展示画面不代表已在RV1106上点亮；照片不能用于测量尺寸。当前展示 ${pictured.length} 条${allPhotos?'（全部候选）':'（当前初筛保留项）'}。`;")
s=s.replace("for(const el of document.querySelectorAll('input,select'))","$('allphotos').onclick=()=>{allPhotos=!allPhotos;$('allphotos').textContent=allPhotos?'只看初筛保留项图片':'浏览全部候选图片';render()};for(const el of document.querySelectorAll('input,select'))")
p.write_text(s,encoding='utf-8')
